std::fs::read_dir(folder)
        .ok()?
        .filter_map(|entry| {
            let entry = entry.ok()?;
            if !entry.file_type().is_ok_and(|kind| kind.is_file()) {
                return None;
            }

            let candidate = entry.path();
            let extension = candidate.extension()?.to_string_lossy().to_lowercase();
            if !SIDECAR_EXTENSIONS.contains(&extension.as_str()) {
                return None;
            }

            let stem = candidate.file_stem()?.to_string_lossy().to_lowercase();
            let tag = stem.strip_prefix(&prefix)?;

            (!tag.is_empty() && Some(tag) != own_extension.as_deref()).then_some(candidate)
        }).collect

engine_processes::hidden_command("ffprobe")
        .args([
            "-v",
            "error",
            "-err_detect",
            "ignore_err",
            "-fflags",
            "+genpts+discardcorrupt+igndts",
            // No `-select_streams`, because the streams wanted are two kinds of stream and a
            // selection names one of them: `v:0` is the picture on its own and `s` would be the
            // subtitles on their own, so the one selection that could carry both does not exist.
            // Asking for the whole header and reading the two kinds out of it is what makes this
            // one pass rather than two (see `VideoHeader`).
            //
            // `width` and `height` are asked of every stream rather than only of a picture, which
            // is what puts a `width=N/A` in the output for every subtitle stream — see
            // `parse_video_picture`, where that line is the reason the picture is read off the
            // first video stream rather than off whichever line came last. `codec_name` rides
            // along for the same shape of reason: it is the one field the extraction needs and
            // the header already holds, so asking for it here saves the second read of the file
            // the extraction's command would otherwise be built from (see `parse_stream_codecs`).
            //
            // Both of those, and `stream_disposition=default` (which is what marks the player's
            // own first choice, see `parse_subtitle_streams`), exist in the list for the
            // subtitle answers alone — so where the `Subtitles` switch is off they are
            // asked for not at all, and the header pass never names a subtitle stream. The
            // parsers tolerate their absence: they key off lines that are simply not printed
            // (see `probe_video_geometry`, which zeroes the answers anyway, because
            // `codec_type=subtitle` is still asked of every stream and so still prints).
            "-show_entries",
            if subtitles_wanted() {
                "stream=index,codec_type,codec_name,width,height:stream_disposition=default:format=duration"
            } else {
                "stream=index,codec_type,width,height:format=duration"
            },
            "-of",
            "default=noprint_wrappers=1",
        ])
        .arg(path)
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn().ok

